// PRIMARY: consensus/types/src/beacon_state.rs:get_beacon_proposer_index (lines 1135-1161)
pub fn get_beacon_proposer_index(&self, slot: Slot, spec: &ChainSpec) -> Result<usize, Error> {
    let epoch = slot.epoch(E::slots_per_epoch());
    if epoch != self.current_epoch() {
        return Err(Error::SlotOutOfBounds);
    }

    if let Ok(proposer_lookahead) = self.proposer_lookahead() {
        // Post-Fulu
        let index = slot.as_usize().safe_rem(E::slots_per_epoch() as usize)?;
        proposer_lookahead
            .get(index)
            .ok_or(Error::PleaseNotifyTheDevs(...))
            .map(|index| *index as usize)
    } else {
        // Pre-Fulu
        let seed = self.get_beacon_proposer_seed(slot, spec)?;
        let indices = self.get_active_validator_indices(epoch, spec)?;
        self.compute_proposer_index(&indices, &seed, spec)
    }
}

