pub fn get_seed(
    &self,
    epoch: Epoch,
    domain_type: Domain,
    spec: &ChainSpec,
) -> Result<Hash256, Error> {
    // Uses randao mix from epoch - MIN_SEED_LOOKAHEAD - 1
    let mix = {
        let i = epoch
            .safe_add(E::EpochsPerHistoricalVector::to_u64())?
            .safe_sub(spec.min_seed_lookahead)?
            .safe_sub(1)?;
        let i_mod = i.as_usize().safe_rem(self.randao_mixes().len())?;
        self.randao_mixes().get(i_mod)...
    };
    // MIN_SEED_LOOKAHEAD default: Epoch::new(1), MAX_SEED_LOOKAHEAD: Epoch::new(4)
    // Seed is computed from randao mix of (epoch - MIN_SEED_LOOKAHEAD - 1)

