// PRIMARY: consensus/types/src/chain_spec.rs:BlobSchedule (lines 1509-1576)
pub struct BlobSchedule {
    schedule: Vec<BlobParameters>,
    skip_serializing: bool,
}

impl BlobSchedule {
    pub fn new(mut vec: Vec<BlobParameters>) -> Self {
        // reverse sort by epoch (DESCENDING order - highest epoch first)
        vec.sort_by(|a, b| b.epoch.cmp(&a.epoch));
        Self { schedule: vec, skip_serializing: false }
    }

    pub fn blob_parameters_for_epoch(&self, epoch: Epoch) -> Option<BlobParameters> {
        self.schedule
            .iter()
            .find(|entry| epoch >= entry.epoch)  // finds first (highest) matching epoch
            .cloned()
    }
}
// Sorted descending at construction time in BlobSchedule::new

